attribute-definition.description:
Return style configurations for Apple Pay button (cart, billing, PDP, PVP, minicart)
Available values: buttonStyle: 'black', // black, white, white-outline type: 'plain', // add-money, book, buy, check-out, continue, contribute, donate, order, pay, plain, reload, rent, set-up, subscribe, support, tip, top-up,
Default value: { "cart":{"buttonStyle":"black", "type": "pay"}, "billing":{"buttonStyle":"black", "type": "pay"} "minicart":{"buttonStyle":"black", "type": "pay"}, "pdp":{"buttonStyle":"black", "type": "pay"}, "pvp":{"buttonStyle":"black", "type": "pay"}, }
